import {beginBottomDialogue} from './bottom-dialogue.js';
import {ULTIMATE_CINEMATIC_STEPS,cinematicSteps} from '../engine/ultimate-rules.js';
import {SABER_META} from './saber-meta.js';
import {saberPose} from '../characters/saber.js';
import {personalCaster} from '../engine/personal-ultimate.js';
export function saberSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=SABER_META[key];if(!im?.complete||!im.naturalWidth||!m)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(m.columns-1,col))*w,Math.max(0,Math.min(m.rows-1,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawSaberActor(ctx,images,d,f,hurt=false,override=null){if(f.introAge!=null&&f.introAge<.35)return;const c=personalCaster(d,f),a=d.personalUltimate?.attack;let pose=override||saberPose(f,hurt);if(c?.kind==='excalibur')pose={row:11,frame:Math.min(5,Math.floor((d.personalUltimate.cinematic?.elapsed??ULTIMATE_CINEMATIC_STEPS+(d.tick-c.born))/16))};else if(a?.kind==='excalibur'&&a.ownerUid===f.uid&&d.tick-a.launch<36)pose={row:12,frame:Math.min(5,Math.floor((d.tick-a.launch)/6))};if(f.state==='defeat')pose={row:6,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};saberSprite(ctx,images,f.introAge!=null?'saber_intro':'saber',pose.row,pose.frame,f.x,f.y,.86,0,f.face);}
export function drawSaberBack(ctx,images,d,clock){for(const f of d.fighters)if(f.id==='saber'&&f.hp>0){if(f.introAge!=null){const age=f.introAge;ctx.save();ctx.globalAlpha=Math.min(1,age*5,(2.5-age)*5);saberSprite(ctx,images,'saber_intro_vfx',0,Math.min(5,Math.floor(age/2.5*6)),f.x,f.y,.7);if(age>.9&&age<2.15)saberSprite(ctx,images,'saber_intro_vfx',1,Math.min(5,Math.floor((age-.9)/1.25*6)),f.x,f.y-60,.6);ctx.restore();}else if(d.tick<f.avalonEnd){ctx.save();ctx.globalAlpha=.65;saberSprite(ctx,images,'saber_vfx',3,2+Math.floor(clock*7)%3,f.x,f.y-40,.9);ctx.restore();}}}
export function drawSaberWorld(ctx,images,d){const a=d.personalUltimate?.attack;if(a?.kind==='excalibur'&&a.phase==='warning'){ctx.save();ctx.strokeStyle='#ffe197';ctx.lineWidth=2;ctx.setLineDash([14,9]);for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(a.x-a.dy*75*side,a.y+a.dx*75*side);ctx.lineTo(a.x+a.dx*1750-a.dy*75*side,a.y+a.dy*1750+a.dx*75*side);ctx.stroke();}ctx.restore();saberSprite(ctx,images,'saber_ultimate_vfx',0,Math.min(5,Math.floor((d.tick-a.born)/6)),a.x,a.y-65,.8);}for(const f of d.fighters)if(f.id==='saber'&&f.introAge!=null&&f.introAge>1.35&&f.introAge<2.05){ctx.save();ctx.globalAlpha=.55;saberSprite(ctx,images,'saber_intro_vfx',2,Math.min(5,Math.floor((f.introAge-1.35)/.7*6)),f.x,f.y-65,.7);ctx.restore();}}
export function drawSaberShot(ctx,images,s,x,y,clock){const ultimate=s.kind==='excalibur',row=ultimate||s.kind==='strikeair'?2:0,col=ultimate?Math.floor(clock*14)%6:s.kind==='strikeair'?2+Math.floor(clock*12)%3:1+Math.floor(clock*12)%3;saberSprite(ctx,images,ultimate?'saber_ultimate_vfx':'saber_vfx',row,col,x,y,ultimate?1.55:.85,Math.atan2(s.vy,s.vx));}
export function drawSaberChat(ctx,images,c,line='Excalibur!',reduced=false){const p=c.elapsed/cinematicSteps(c);beginBottomDialogue(ctx,'saber');ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));const slide=reduced?0:Math.max(0,1-p*9)*65;saberSprite(ctx,images,'saber_dialogue',0,p>.45?1:0,480+slide,310,.8);saberSprite(ctx,images,'saber_dialogue',2,p>.5?1:0,225+slide,315,.23);ctx.textAlign='center';ctx.fillStyle='#fff2c3';ctx.font='bold 17px Georgia';ctx.fillText('SABER',408+slide,266,150);ctx.font='bold 36px Georgia';ctx.fillText(line,575+slide,328,480);ctx.restore();}
export function drawSaberCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if((c||a)?.kind!=='excalibur')return;if(c)drawSaberChat(ctx,images,c,undefined,reduced);else if(a.phase==='travel'&&d.tick-a.launch<48){ctx.save();ctx.globalAlpha=Math.min(1,(48-d.tick+a.launch)/12);saberSprite(ctx,images,'saber_dialogue',3,0,480,92,.6);ctx.restore();}}
